xs = [-100,-80,-60,-40,-20,0,20,40,60,80,100]
ys = [4,8,13,23,34,36,32,24,12,8,0]

def interp(x, xs, ys):
    if x < xs[0] or x > xs[-1]:
        return 0.0
    for i in range(len(xs)-1):
        if xs[i] <= x <= xs[i+1]:
            t = (x-xs[i])/(xs[i+1]-xs[i])
            return ys[i]*(1-t)+ys[i+1]*t
    return 0.0

def coverage(pitch):
    n = 40
    vals = []
    for i in range(n):
        off = pitch * i / n
        s = 0.0
        for k in range(-15, 16):
            s += interp(off - k*pitch, xs, ys)
        vals.append(s)
    return min(vals), max(vals), sum(vals)/len(vals)

for p in [25,30,40,45,50,55,60,70,80,100]:
    print(p, tuple(round(v,1) for v in coverage(p)))

# trapezoid integral
integ = 0
for i in range(len(xs)-1):
    integ += (ys[i]+ys[i+1])/2 * (xs[i+1]-xs[i])
print('integral', integ)
